INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kann ich einer Variable mehrfach Werte zuweisen?', 2, '[{"text": "Ja", "correct": true, "because": "Werte sind veränderlich"}, {"text": "Nein", "correct": false, "because": "Nur Konstanten unveränderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer Zuweisung?', 3, '[{"text": "Variable mit Wert füllen", "correct": true, "because": "Definiert Zustand"}, {"text": "Speicher freigeben", "correct": false, "because": "Anderer Prozess"}, {"text": "UI anpassen", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen den Scope?', 5, '[{"text": "Deklarationsort", "correct": true, "because": "Bestimmt Sichtbarkeit"}, {"text": "Blockstruktur", "correct": true, "because": "Begrenzt Gültigkeit"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}, {"text": "Netzwerkverbindung", "correct": false, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Scope ist sprachabhängig. b) Zuweisung ändert den Datentyp.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Datentyp bleibt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einer Zuweisung?', 4, '[{"text": "Datentyp-Kompatibilität", "correct": false, "because": "Muss passen"}, {"text": "Aktueller Wert", "correct": false, "because": "Wird überschrieben"}, {"text": "Bildauflösung", "correct": true, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob der Scope immer lokal ist?', 2, '[{"text": "Nein", "correct": true, "because": "Kann auch global sein"}, {"text": "Ja", "correct": false, "because": "Abhängig von Deklaration"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Wert wähle ich für eine bool-Variable?', 3, '[{"text": "true", "correct": true, "because": "Gültiger Wert"}, {"text": "42", "correct": false, "because": "Numerisch"}, {"text": "text", "correct": false, "because": "String"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Regeln gelten für den Scope?', 5, '[{"text": "Sichtbarkeit im Block", "correct": true, "because": "Begrenzt Zugriff"}, {"text": "Lebensdauer der Variable", "correct": true, "because": "Endet mit Block"}, {"text": "Dynamische Änderung", "correct": false, "because": "Statisch definiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Zuweisung kann Fehler werfen. b) Scope ist immer global. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Scope variiert"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Zuweisung?', 4, '[{"text": "Definierte Variable", "correct": false, "because": "Muss existieren"}, {"text": "Kompatibler Wert", "correct": false, "because": "Typ muss passen"}, {"text": "Grafikeditor", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ich im globalen Scope lokal zuweisen?', 2, '[{"text": "Ja", "correct": true, "because": "Scope unabhängig von Zuweisung"}, {"text": "Nein", "correct": false, "because": "Technisch möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein klarer Scope?', 4, '[{"text": "Fehlervermeidung", "correct": true, "because": "Klare Grenzen"}, {"text": "Wartbarkeit", "correct": true, "because": "Übersichtlicher Code"}, {"text": "Datenkompression", "correct": false, "because": "Kein Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Zuweisung den Scope ändert. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Scope bleibt fest"}, {"text": "Ja", "correct": false, "because": "Nur Wert ändert sich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einer Zuweisung?', 3, '[{"text": "Typkompatibilität", "correct": true, "because": "Vermeidet Fehler"}, {"text": "Schnelle Ausführung", "correct": false, "because": "Korrektheit zählt"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Lokaler Scope schützt Daten. b) Zuweisung ist einmalig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Zuweisung wiederholbar"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken gibt es bei falscher Zuweisung?', 5, '[{"text": "Typkonflikte", "correct": true, "because": "Kann Fehler werfen"}, {"text": "Datenverlust", "correct": true, "because": "Überschreibt Werte"}, {"text": "Schnellere Laufzeit", "correct": false, "because": "Kein Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim Scope unwichtig?', 3, '[{"text": "Deklarationsort", "correct": false, "because": "Definiert Sichtbarkeit"}, {"text": "Blockgrenzen", "correct": false, "because": "Bestimmen Gültigkeit"}, {"text": "Serverleistung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ich außerhalb des Scopes zugreifen?', 3, '[{"text": "Nein", "correct": true, "because": "Scope begrenzt Zugriff"}, {"text": "Ja", "correct": false, "because": "Nur innerhalb möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Zuweisung den Typ ändert?', 2, '[{"text": "Nein", "correct": true, "because": "Typ bleibt fest"}, {"text": "Ja", "correct": false, "because": "Nur in dynamischen Sprachen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Wert wähle ich für eine int-Variable?', 4, '[{"text": "42", "correct": true, "because": "Ganze Zahl passt"}, {"text": "3.14", "correct": false, "because": "Dezimalzahl"}, {"text": "true", "correct": false, "because": "Boolescher Wert"}]');
